, \'4MTP0043-04\', \'4MTP0044-01\', \'4MTP0044-02\', \'4MTP0044-03\', \'4MTP0044-04\', \'4MTP0044-05\', \'4MTP0044-06\', \'4MTP0045-01\', \'4MTP0045-02\', \'4MTP0045-04\', \'4MTP0052-02\', \'4MTP0052-03\', \'4MTP0053-01\', \'4MTP0054-01\', \'4MTP0055-01\', \'4MTP0055-02\', \'4MTP0055-05\', \'4MTP0056-01\', \'4MTP0056-02\', \'4MTP0056-03\', \'4MTP0056-04\', \'4MTP0056-05\', \'4MTP0060-01\', \'4MTP0060-02\', \'4MTP0060-03\', \'4MTP0060-04\', \'4MTR0123-01\', \'4MTR0123-02\', \'4MTR0123-03\', \'4MTR0123-04\', \'4MTR0123-05\', \'4MTR0123-06\' ) then \'EOSS\' ELSE \'Fresh\' END AS SKU_STATUS, from snitch_db.maplemonk.offline_master; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.STORE_CATEGORY_DELTA_EOSS AS SELECT *, round( GREATEST( ideal_category_qty - ( eoss_inventory + eoss_jit_units - (eoss_sales_l7 / 7.0) * lead_time ), 0 ),0) AS delta FROM ( SELECT branch_code, marketplace_mapped, new_category, ROUND(0.35 * MAX(base_stock), 0) AS eoss_base_stock, CASE new_category WHEN \'Cargo Pants\' THEN 0.03 WHEN \'Co-ords\' THEN 0.00 WHEN \'Hoodies\' THEN 0.01 WHEN \'Jackets\' THEN 0.03 WHEN \'Jeans\' THEN 0.04 WHEN \'Joggers & Trackpants\' THEN 0.01 WHEN \'Overshirt\' THEN 0.02 WHEN \'Shirts\' THEN 0.44 WHEN \'Shorts\' THEN 0.01 WHEN \'Sweaters\' THEN 0.02 WHEN \'Sweatshirts\' THEN 0.01 WHEN \'Trousers\' THEN 0.18 WHEN \'T-Shirts\' THEN 0.20 ELSE 0 END AS ideal_category_mix, ROUND( 0.35 * MAX(base_stock) * CASE new_category WHEN \'Cargo Pants\' THEN 0.03 WHEN \'Co-ords\' THEN 0.00 WHEN \'Hoodies\' THEN 0.01 WHEN \'Jackets\' THEN 0.03 WHEN \'Jeans\' THEN 0.04 WHEN \'Joggers & Trackpants\' THEN 0.01 WHEN \'Overshirt\' THEN 0.02 WHEN \'Shirts\' THEN 0.44 WHEN \'Shorts\' THEN 0.01 WHEN \'Sweaters\' THEN 0.02 WHEN \'Sweatshirts\' THEN 0.01 WHEN \'Trousers\' THEN 0.18 WHEN \'T-Shirts\' THEN 0.20 ELSE 0 END, 0 ) AS ideal_category_qty, SUM(inventory) AS eoss_inventory, SUM(jit_qty) AS eoss_jit_units, SUM(sales_last_7_days) AS eoss_sales_l7, CASE WHEN UPPER(MAX(cluster)) = \'AP\' THEN 5 WHEN UPPER(MAX(cluster)) = \'ASSAM\' THEN 7 WHEN UPPER(MAX(cluster)) = \'BANGALORE\' THEN 3 WHEN UPPER(MAX(cluster)) = \'CHHATTISGARH\' THEN 7 WHEN UPPER(MAX(cluster)) = \'DELHI\' THEN 8 WHEN UPPER(MAX(cluster)) = \'GUJARAT\' THEN 6 WHEN UPPER(MAX(cluster)) = \'HARYANA\' THEN 8 WHEN UPPER(MAX(cluster)) = \'HYDERABAD\' THEN 5 WHEN UPPER(MAX(cluster)) = \'KARNATAKA\' THEN 3 WHEN UPPER(MAX(cluster)) = \'KERALA\' THEN 4 WHEN UPPER(MAX(cluster)) = \'MAHARASHTRA\' THEN 6 WHEN UPPER(MAX(cluster)) = \'MANGALORE\' THEN 3 WHEN UPPER(MAX(cluster)) = \'MP\' THEN 6 WHEN UPPER(MAX(cluster)) = \'MUMBAI\' THEN 6 WHEN UPPER(MAX(cluster)) = \'ODISHA\' THEN 6 WHEN UPPER(MAX(cluster)) = \'RAJASTHAN\' THEN 7 WHEN UPPER(MAX(cluster)) = \'TAMIL NADU\' THEN 4 WHEN UPPER(MAX(cluster)) = \'UTTAR PRADESH\' THEN 8 WHEN UPPER(MAX(cluster)) = \'UTTARAKHAND\' THEN 9 ELSE 0 END AS lead_time FROM snitch_db.maplemonk.offline_master_eoss WHERE sku_status = \'EOSS\' AND branch_code IS NOT NULL AND base_stock IS NOT NULL GROUP BY branch_code, marketplace_mapped, new_category ); CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.STORE_SIZE_DELTA_EOSS AS SELECT *, ROUND( GREATEST( ideal_size_qty - ( size_inventory + size_jit ), 0 ), 0 ) AS delta FROM ( SELECT branch_code, marketplace_mapped, size, ROUND(0.35 * MAX(base_stock), 0) AS eoss_base_stock, CASE size WHEN \'XS\' THEN 0.00 WHEN \'S\' THEN 0.14 WHEN \'M\' THEN 0.29 WHEN \'L\' THEN 0.29 WHEN \'XL\' THEN 0.15 WHEN \'XXL\' THEN 0.13 ELSE 0 END AS ideal_size_mix, ROUND( 0.35 * MAX(base_stock) * CASE size WHEN \'XS\' THEN 0.00 WHEN \'S\' THEN 0.14 WHEN \'M\' THEN 0.29 WHEN \'L\' THEN 0.29 WHEN \'XL\' THEN 0.15 WHEN \'XXL\' THEN 0.13 ELSE 0 END, 0 ) AS ideal_size_qty, SUM(size_inventory) AS size_inventory, SUM(size_jit) AS size_jit, FROM ( SELECT branch_code, marketplace_mapped, cluster, base_stock, sales_last_7_days, \'XS\' AS size, xs_units AS size_inventory, jit_xs_units AS size_jit FROM snitch_db.maplemonk.offline_master_eoss WHERE sku_status = \'EOSS\' UNION ALL SELECT branch_code, marketplace_mapped, cluster, base_stock, sales_last_7_days, \'S\', s_units, jit_s_units FROM snitch_db.maplemonk.offline_master_eoss WHERE sku_status = \'EOSS\' UNION ALL SELECT branch_code, marketplace_mapped, cluster, base_stock, sales_last_7_days, \'M\', m_units, jit_m_units FROM snitch_db.maplemonk.offline_master_eoss WHERE sku_status = \'EOSS\' UNION ALL SELECT branch_code, marketplace_mapped, cluster, base_stock, sales_last_7_days, \'L\', l_units, jit_l_units FROM snitch_db.maplemonk.offline_master_eoss WHERE sku_status = \'EOSS\' UNION ALL SELECT branch_code, marketplace_mapped, cluster, base_stock, sales_last_7_days, \'XL\', xl_units, jit_xl_units FROM snitch_db.maplemonk.offline_master_eoss WHERE sku_status = \'EOSS\' UNION ALL SELECT branch_code, marketplace_mapped, cluster, base_stock, sales_last_7_days, \'XXL\', xxl_units, jit_2xl_units FROM snitch_db.maplemonk.offline_master_eoss WHERE sku_status = \'EOSS\' ) where branch_code IS NOT NULL AND base_stock IS NOT NULL GROUP BY branch_code, marketplace_mapped, size );",
                    "transaction": true
                }
            ) }}
